import { useState, useMemo } from 'react';
import { Table, TableHead, TableBody, TableRow, TableHeaderCell, TableCell, Badge, Pagination } from '@jinx-ui/react';

interface User {
  id: string | number;
  name: string;
  role: string;
  status: 'active' | 'disabled';
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));

  const currentUsers = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, page]);

  return (
    <div className="jx-stack jx-gap-md">
      <Table className="jx-table">
        <TableHead>
          <TableRow>
            <TableHeaderCell>Имя</TableHeaderCell>
            <TableHeaderCell>Роль</TableHeaderCell>
            <TableHeaderCell>Статус</TableHeaderCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {currentUsers.map((user) => (
            <TableRow key={user.id}>
              <TableCell>{user.name}</TableCell>
              <TableCell>{user.role}</TableCell>
              <TableCell>
                {user.status === 'active' ? (
                  <Badge className="jx-badge-success">Активен</Badge>
                ) : (
                  <Badge className="jx-badge-neutral">Отключён</Badge>
                )}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>

      <Pagination
        className="jx-pagination"
        currentPage={page}
        pageCount={pageCount}
        onPageChange={setPage}
      />
    </div>
  );
}

